  const PX16 = '/^(1[6-9]|[2-9][0-9])px$/', PX18 = '/^(1[89]|[2-9][0-9])px$/', PX30 = '/^[3-9][0-9]px$/';
  const HEX6 = '/^#[0-9a-f]{6}$/';
  const DARK3 = '/^#[0-3][0-9a-f][0-3][0-9a-f][0-3][0-9a-f]$/', DARK5 = '/^#[0-5][0-9a-f][0-5][0-9a-f][0-5][0-9a-f]$/';
  const LIGHT = '/^(#[c-f][0-9a-f][c-f][0-9a-f][c-f][0-9a-f]|white)$/';
